def E(slug, nome, inicio, fim, props=(), seta=(), props_fim=(), novo=False, series=None, reps=None, instr=None, curva=0.25):
    return dict(slug=slug, nome=nome, novo=novo, series=series, reps=reps, instr=instr,
                cena=dict(inicio=inicio, fim=fim, props=list(props), props_fim=list(props_fim), seta=list(seta), curva=curva))

